if op == "checkpoint":
    if set(req.keys()) != {"op"}:
        raise EventError()
    return {"checkpoint": self._checkpoint()}

if op == "open":
    if set(req.keys()) != {"op", "flow", "time"}:
        raise EventError()
    fid = req["flow"]
    T = req["time"]
    if not is_int(fid) or not (0 <= fid <= INT32_MAX):
        raise EventError()
    if not is_int(T) or not (0 <= T <= TIME_MAX):
        raise EventError()
    if T < self.last_time:
        raise EventError()
    if fid in self.flows:
        raise EventError()
    if len(self.flows) >= 4096:
        raise EventError()
    events = self.expire(T)
    f = Flow()
    f.fid = fid
    f.last = T
    self.flows[fid] = f
    heapq.heappush(self.heap, (T, fid))
    self.last_time = T
    return {"events": events}

